<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { api } from '../api'
const props=defineProps(['demoMode'])
const emit=defineEmits(['error'])
const versions=ref([]),builtins=ref([]),experiments=ref([]),cases=ref([]),runs=ref([]),busy=ref(false),message=ref(''),tab=ref('prompts')
const form=ref({stage:'Article',name:'',instruction:'',options:{temperature:0.4,max_tokens:4000,model:''},activate:false})
const experiment=ref({stage:'Article',control_id:'',treatment_id:'',percentage:50,enabled:true})
const selectedCases=ref([]),variantA=ref(''),variantB=ref('')
const stageVersions=computed(()=>versions.value.filter(v=>v.stage===experiment.value.stage))
const articleVersions=computed(()=>versions.value.filter(v=>v.stage==='Article'))
let timer
async function load(){try{const [p,e,c,r]=await Promise.all([api('/prompts'),api('/prompt-experiments'),api('/evaluation-cases'),api('/evaluations')]);versions.value=p.items;builtins.value=p.builtins;experiments.value=e;cases.value=c;runs.value=r;if(!form.value.instruction)loadBuiltin()}catch(e){emit('error',e.message)}}
function loadBuiltin(){const b=builtins.value.find(v=>v.stage===form.value.stage);if(b){form.value.instruction=b.instruction;form.value.options={temperature:b.options.temperature,max_tokens:b.options.max_tokens,model:''}}}
function copy(v){form.value={stage:v.stage,name:v.name+' · 新版本',instruction:v.instruction,options:{temperature:null,max_tokens:null,model:'',...v.options},activate:false};tab.value='prompts'}
async function save(){busy.value=true;try{await api('/prompts',{method:'POST',body:form.value});form.value.name='';message.value='版本已保存。已有任务保留原提示词，新任务可使用新版本。';await load()}catch(e){emit('error',e.message)}finally{busy.value=false}}
async function activate(id){busy.value=true;try{await api(`/prompts/${id}/activate`,{method:'POST'});message.value='已切换默认版本；若该阶段开启了 A/B，仍按实验分流';await load()}catch(e){emit('error',e.message)}finally{busy.value=false}}
async function saveExperiment(){busy.value=true;try{await api('/prompt-experiments',{method:'PUT',body:experiment.value});message.value='A/B配置已保存，按新任务稳定分组；同一幂等请求不会重新分组';await load()}catch(e){emit('error',e.message)}finally{busy.value=false}}
async function evaluate(){busy.value=true;try{const result=await api('/evaluations',{method:'POST',body:{case_ids:selectedCases.value,prompt_ids:[variantA.value||'builtin',...(variantB.value?[variantB.value]:[])]}});message.value=`评测已排队，计划生成 ${result.planned_generations} 篇文章`;await load()}catch(e){emit('error',e.message)}finally{busy.value=false}}
onMounted(async()=>{await load();timer=setInterval(async()=>{if(runs.value.some(r=>['queued','running'].includes(r.status)))await load()},2500)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="intro compact"><h2>让每次提示词修改都有依据。</h2><p>版本不可覆盖，任务保存完整快照。用固定样本检验规则，再结合人工评分判断质量。</p></div><div class="detail-tabs"><button :class="{active:tab==='prompts'}" @click="tab='prompts'">提示词版本</button><button :class="{active:tab==='experiments'}" @click="tab='experiments'">A/B 分流</button><button :class="{active:tab==='evaluations'}" @click="tab='evaluations'">固定样本回归</button></div><p v-if="message" class="toast success" role="status">{{message}}</p>
<div v-if="tab==='prompts'" class="library-grid"><form class="panel" @submit.prevent="save"><h3>保存一个新版本</h3><label>阶段<select v-model="form.stage" @change="loadBuiltin"><option value="TopicBatch">选题</option><option value="Article">长文</option><option value="CardPack">卡片提炼</option></select></label><label>版本名称<input v-model="form.name" required maxlength="100" placeholder="例如：先给类比，再写步骤"></label><label>提示词<textarea v-model="form.instruction" rows="16" required minlength="10" maxlength="16000"></textarea></label><div class="form-grid"><label>采样温度<input v-model.number="form.options.temperature" type="number" min="0" max="2" step="0.1"></label><label>最大输出 Token<input v-model.number="form.options.max_tokens" type="number" min="256" max="32000"></label></div><label>指定模型（留空沿用阶段路由）<input v-model="form.options.model" maxlength="200"></label><label class="inline-check"><input v-model="form.activate" type="checkbox">作为之后新任务的默认版本</label><button class="primary" :disabled="busy">保存新版本</button></form><div class="library-list"><article v-for="v in versions" :key="v.id" class="panel"><span class="pill">{{v.stage}} · {{v.active?'当前默认':'历史版本'}}</span><h3>{{v.name}}</h3><p class="muted">{{new Date(v.created_at).toLocaleString('zh-CN')}} · {{v.digest.slice(0,12)}}</p><details><summary>查看完整提示词</summary><pre class="streaming-text">{{v.instruction}}</pre></details><div class="actions wrap"><button @click="copy(v)">复制为新版本</button><button :disabled="busy||v.active" @click="activate(v.id)">启用 / 回滚至此版本</button></div></article><p v-if="!versions.length" class="panel muted">当前使用内置提示词。左侧可直接修改并保存首个自定义版本。</p></div></div>
<div v-if="tab==='experiments'" class="panel"><h3>按新任务进行稳定分组</h3><form @submit.prevent="saveExperiment"><label>阶段<select v-model="experiment.stage" @change="experiment.control_id='';experiment.treatment_id=''"><option value="TopicBatch">选题</option><option value="Article">长文</option><option value="CardPack">卡片</option></select></label><div class="form-grid"><label>A 对照版本<select v-model="experiment.control_id" required><option value="" disabled>选择版本</option><option v-for="v in stageVersions" :key="v.id" :value="v.id">{{v.name}}</option></select></label><label>B 实验版本<select v-model="experiment.treatment_id" required><option value="" disabled>选择版本</option><option v-for="v in stageVersions" :key="v.id" :value="v.id">{{v.name}}</option></select></label><label>B 分配比例（%）<input v-model.number="experiment.percentage" type="number" min="0" max="100"></label></div><label class="inline-check"><input v-model="experiment.enabled" type="checkbox">启用此阶段实验</label><button class="primary" :disabled="busy">保存分流配置</button></form><div v-for="e in experiments" :key="e.id" class="caption-box"><strong>{{e.stage}} · {{e.enabled?'已启用':'已停用'}} · B {{e.percentage}}%</strong><p class="muted">A {{e.control_id.slice(0,8)}} / B {{e.treatment_id.slice(0,8)}}</p><button @click="experiment={stage:e.stage,control_id:e.control_id,treatment_id:e.treatment_id,percentage:e.percentage,enabled:e.enabled}">载入配置</button></div></div>
<template v-if="tab==='evaluations'"><section class="panel"><h3>对同一批输入比较版本</h3><p class="muted">{{props.demoMode?'当前使用演示模型，只验证评测流程。':'将调用当前配置的真实模型，生成次数为样本数 × 版本数。'}} 自动结果是规则符合度，不能代替技术事实核查。</p><div class="case-list"><label v-for="c in cases" :key="c.id" class="inline-check"><input type="checkbox" :value="c.id" v-model="selectedCases">{{c.name}}</label><p v-if="!cases.length" class="muted">先在已完成内容下，将定稿保存为评测样本。</p></div><div class="form-grid"><label>版本 A<select v-model="variantA"><option value="">内置版本</option><option v-for="v in articleVersions" :value="v.id" :key="v.id">{{v.name}}</option></select></label><label>版本 B<select v-model="variantB"><option value="">只测试一个版本</option><option v-for="v in articleVersions" :value="v.id" :key="v.id">{{v.name}}</option></select></label></div><button class="primary" :disabled="busy||!selectedCases.length||selectedCases.length>10" @click="evaluate">开始回归评测（{{selectedCases.length*(variantB?2:1)}}次生成）</button><button @click="load">刷新结果</button></section><section v-for="r in runs" :key="r.id" class="panel"><div class="section-heading"><h3>评测 {{r.id.slice(0,8)}}</h3><span class="pill">{{{queued:'等待执行',running:'正在运行',succeeded:'已完成',failed:'失败'}[r.status]}}</span></div><p v-if="r.error" class="error">{{r.error}}</p><div v-for="result in r.results" :key="result.case_id+result.variant" class="caption-box"><h4>{{result.name}} · {{result.variant_name}}</h4><p>{{result.passed?'规则全部通过':'存在未通过规则'}} · {{(result.score*100).toFixed(0)}}% · {{(result.duration_ms/1000).toFixed(2)}}s</p><ul><li v-for="(value,key) in result.checks" :key="key">{{value?'✓':'×'}} {{key}}</li></ul><details><summary>查看生成文章与参考定稿</summary><h4>本轮输出</h4><pre class="streaming-text">{{result.article.markdown}}</pre><h4>人工参考稿</h4><pre class="streaming-text">{{result.expected.markdown}}</pre></details></div></section></template>
</template>
